import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1785772843000}'),l={name:"guide/getting-started.md"};function n(o,a,r,h,p,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>欢迎使用 ZViewer！本教程将带你从零开始，一步步完成安装、启动、登录、创建房间、添加视频并邀请好友一起观影的完整流程。</p><hr><h2 id="第一步-下载-zviewer" tabindex="-1">第一步：下载 ZViewer <a class="header-anchor" href="#第一步-下载-zviewer" aria-label="Permalink to &quot;第一步：下载 ZViewer&quot;">​</a></h2><p>ZViewer 提供<strong>单文件版</strong>和<strong>源码版</strong>两种运行方式。</p><h3 id="方式一-单文件版-推荐" tabindex="-1">方式一：单文件版（推荐） <a class="header-anchor" href="#方式一-单文件版-推荐" aria-label="Permalink to &quot;方式一：单文件版（推荐）&quot;">​</a></h3><p>无需安装 Node.js 或 npm，下载后解压即可运行。</p><ol><li>打开 <a href="https://github.com/Zero-wyc/ZViewer/releases" target="_blank" rel="noreferrer">ZViewer Releases 页面</a></li><li>根据你的操作系统下载对应压缩包： <ul><li><strong>Windows</strong>：下载 <code>zviewer-windows-x64.zip</code></li><li><strong>Linux</strong>：下载 <code>zviewer-linux-x64.tar.gz</code></li></ul></li><li>解压到任意文件夹（例如 <code>D:\\ZViewer</code> 或 <code>~/ZViewer</code>）</li></ol><p>解压后目录结构如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>zviewer-windows-x64/</span></span>
<span class="line"><span>├── zviewer-backend.exe     # 后端服务</span></span>
<span class="line"><span>├── zviewer-frontend.exe    # 前端静态文件服务</span></span>
<span class="line"><span>├── zviewer-cert.exe        # SSL 证书工具</span></span>
<span class="line"><span>├── start.bat               # 启动脚本（Windows）</span></span>
<span class="line"><span>└── start.sh                # 启动脚本（Linux）</span></span></code></pre></div><h3 id="方式二-源码版" tabindex="-1">方式二：源码版 <a class="header-anchor" href="#方式二-源码版" aria-label="Permalink to &quot;方式二：源码版&quot;">​</a></h3><p>适合有 Node.js 开发经验的用户。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆项目</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Zero-wyc/ZViewer.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ZViewer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装依赖</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><hr><h2 id="第二步-启动服务" tabindex="-1">第二步：启动服务 <a class="header-anchor" href="#第二步-启动服务" aria-label="Permalink to &quot;第二步：启动服务&quot;">​</a></h2><h3 id="单文件版启动" tabindex="-1">单文件版启动 <a class="header-anchor" href="#单文件版启动" aria-label="Permalink to &quot;单文件版启动&quot;">​</a></h3><p><strong>Windows</strong>：双击 <code>start.bat</code>，或打开终端运行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 交互菜单模式</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start.bat</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或直接启动</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">start.bat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> start</span></span></code></pre></div><p><strong>Linux</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>启动后终端会显示交互菜单：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>========================================</span></span>
<span class="line"><span>  ZViewer 服务管理</span></span>
<span class="line"><span>========================================</span></span>
<span class="line"><span>  1) 启动服务 (HTTP)</span></span>
<span class="line"><span>  2) 仅启动后端（可选 HTTP / HTTPS）</span></span>
<span class="line"><span>  3) 停止服务</span></span>
<span class="line"><span>  4) 重启服务</span></span>
<span class="line"><span>  5) 查看状态</span></span>
<span class="line"><span>  6) 查看日志</span></span>
<span class="line"><span>  7) 一键签发 SSL 证书</span></span>
<span class="line"><span>  8) HTTPS 启动（自动签发证书）</span></span>
<span class="line"><span>  9) 构建前后端（源码版）</span></span>
<span class="line"><span>  0) 退出</span></span></code></pre></div><p>初次使用选择 <strong>1) 启动服务 (HTTP)</strong> 即可。</p><h3 id="源码版启动" tabindex="-1">源码版启动 <a class="header-anchor" href="#源码版启动" aria-label="Permalink to &quot;源码版启动&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">start-prod.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start-prod.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Linux / macOS</span></span></code></pre></div><h3 id="启动后访问" tabindex="-1">启动后访问 <a class="header-anchor" href="#启动后访问" aria-label="Permalink to &quot;启动后访问&quot;">​</a></h3><p>服务启动后，打开浏览器访问：</p><ul><li><strong>HTTP 模式</strong>：<code>http://localhost:4173</code></li><li><strong>HTTPS 模式</strong>：<code>https://localhost:3333</code></li></ul><hr><h2 id="第三步-登录系统" tabindex="-1">第三步：登录系统 <a class="header-anchor" href="#第三步-登录系统" aria-label="Permalink to &quot;第三步：登录系统&quot;">​</a></h2><p>首次启动时系统会自动创建超级管理员账号：</p><table tabindex="0"><thead><tr><th>用户名</th><th>密码</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>root</code></td></tr></tbody></table><ol><li>打开浏览器访问 <code>http://localhost:4173</code></li><li>你会看到首页，底部显示 🟢 <strong>已连接</strong> 表示服务运行正常</li><li>点击页面中的「加入房间」或「房间列表」按钮，会跳转到登录页面</li><li>输入用户名 <code>root</code>、密码 <code>root</code>，点击「登录」</li></ol><blockquote><p>系统会自动为未登录用户分配<strong>游客（guest）身份</strong>，游客可以加入房间观看，但不能创建房间。</p></blockquote><hr><h2 id="第四步-修改默认密码-重要" tabindex="-1">第四步：修改默认密码（重要！） <a class="header-anchor" href="#第四步-修改默认密码-重要" aria-label="Permalink to &quot;第四步：修改默认密码（重要！）&quot;">​</a></h2><p>生产环境部署后<strong>必须立即修改默认密码</strong>，否则他人可登录你的管理后台。</p><ol><li>登录后，点击右上角用户菜单（显示你的用户名），选择「个人资料」</li><li>在个人资料页点击「编辑信息」按钮</li><li>在弹出的编辑窗口中，<strong>右侧列</strong>找到「修改密码」</li><li>输入原密码 <code>root</code>、新密码（至少 4 位）、确认新密码</li><li>点击「确认修改」</li></ol><blockquote><p>同时建议修改 JWT 密钥（<code>JWT_ACCESS_SECRET</code> 和 <code>JWT_REFRESH_SECRET</code>），详见<a href="/dev/env">环境变量</a>。</p></blockquote><hr><h2 id="第五步-创建房间" tabindex="-1">第五步：创建房间 <a class="header-anchor" href="#第五步-创建房间" aria-label="Permalink to &quot;第五步：创建房间&quot;">​</a></h2><ol><li>修改完密码后，回到首页（点击左上角 ZViewer 图标或导航栏）</li><li>点击 <strong>「开始共享」</strong> 按钮</li><li>你会进入房间页面，此时因为还没有 roomId，会显示<strong>创建房间面板</strong></li><li>选择房间模式： <ul><li><strong>一起看（watch-together）</strong>：所有人同步观看同一部影片</li><li><strong>屏幕共享（screen-share）</strong>：分享端共享屏幕画面</li></ul></li><li>创建成功后，页面自动进入房间</li></ol><blockquote><p>如果「开始共享」按钮被禁用，说明管理员设置了&quot;仅管理员可创建房间&quot;，请联系管理员或使用 <code>root</code> 账号登录。</p></blockquote><hr><h2 id="第六步-认识房间界面" tabindex="-1">第六步：认识房间界面 <a class="header-anchor" href="#第六步-认识房间界面" aria-label="Permalink to &quot;第六步：认识房间界面&quot;">​</a></h2><p>进入房间后，你会看到以下界面布局：</p><h3 id="顶部区域" tabindex="-1">顶部区域 <a class="header-anchor" href="#顶部区域" aria-label="Permalink to &quot;顶部区域&quot;">​</a></h3><ul><li><strong>返回按钮</strong>：退出房间</li><li><strong>房间名称</strong>：显示当前房间名，房主可点击编辑</li><li><strong>模式切换</strong>：<code>一起看</code> / <code>投屏</code> 切换（房主可用）</li></ul><h3 id="中间区域" tabindex="-1">中间区域 <a class="header-anchor" href="#中间区域" aria-label="Permalink to &quot;中间区域&quot;">​</a></h3><ul><li><strong>播放器</strong>：视频播放区域，占大部分空间</li></ul><h3 id="底部控制卡片-三列网格" tabindex="-1">底部控制卡片（三列网格） <a class="header-anchor" href="#底部控制卡片-三列网格" aria-label="Permalink to &quot;底部控制卡片（三列网格）&quot;">​</a></h3><ul><li><strong>房间信息</strong>（左侧）：显示房间号、分享链接、观众列表、权限设置</li><li><strong>影片列表</strong>（中间）：当前房间已添加的影片</li><li><strong>添加影片</strong>（右侧）：从各种视频源添加影片</li></ul><h3 id="右侧面板" tabindex="-1">右侧面板 <a class="header-anchor" href="#右侧面板" aria-label="Permalink to &quot;右侧面板&quot;">​</a></h3><ul><li><strong>评论/弹幕/聊天</strong>：与观众实时互动</li></ul><hr><h2 id="第七步-邀请好友加入" tabindex="-1">第七步：邀请好友加入 <a class="header-anchor" href="#第七步-邀请好友加入" aria-label="Permalink to &quot;第七步：邀请好友加入&quot;">​</a></h2><p>你的房间创建后，需要告诉好友房间号：</p><ol><li>在房间中，找到底部左侧的<strong>房间信息面板</strong></li><li>切换到「信息」Tab</li><li>你会看到： <ul><li><strong>房间号</strong>：一串数字 ID（例如 <code>123456</code>）</li><li><strong>分享链接</strong>：可直接复制给好友的完整链接</li></ul></li><li>点击房间号或链接旁的复制按钮，发送给好友</li></ol><p>好友可以通过以下方式加入：</p><p><strong>方式一：通过房间号</strong></p><ol><li>在首页点击「加入房间」按钮</li><li>输入房间号，点击「加入」</li></ol><p><strong>方式二：通过房间列表</strong></p><ol><li>在首页点击「房间列表」按钮</li><li>从列表中找到你的房间，点击「加入房间」</li></ol><p><strong>方式三：通过分享链接</strong></p><ol><li>直接打开你分享的链接</li></ol><blockquote><p>如果房间设置了密码，好友加入时需要输入密码。如果开启了&quot;需要审批&quot;，房主会收到加入请求通知，需点击同意。</p></blockquote><hr><h2 id="第八步-添加视频" tabindex="-1">第八步：添加视频 <a class="header-anchor" href="#第八步-添加视频" aria-label="Permalink to &quot;第八步：添加视频&quot;">​</a></h2><p>房间创建后，需要添加视频才能开始观看。</p><ol><li>在房间界面，找到底部右侧的**「添加影片」面板**</li><li>选择你想要的视频来源：</li></ol><h3 id="使用-bilibili-视频-最常用" tabindex="-1">使用 Bilibili 视频（最常用） <a class="header-anchor" href="#使用-bilibili-视频-最常用" aria-label="Permalink to &quot;使用 Bilibili 视频（最常用）&quot;">​</a></h3><ol><li>在「添加影片」面板中选择 <strong>B站</strong> Tab</li><li>粘贴 Bilibili 视频链接、BV 号或 AV 号 <ul><li>例如：<code>https://www.bilibili.com/video/BV1GJ411x7o</code> 或 <code>BV1GJ411x7o</code></li></ul></li><li>点击解析按钮，等待解析完成</li><li>解析成功后，视频会自动添加到影片列表中</li></ol><h3 id="使用-mp4-直链" tabindex="-1">使用 MP4 直链 <a class="header-anchor" href="#使用-mp4-直链" aria-label="Permalink to &quot;使用 MP4 直链&quot;">​</a></h3><ol><li>选择 <strong>直接链接</strong> Tab</li><li>输入视频文件的直链 URL（如 <code>https://example.com/video.mp4</code>）</li><li>点击添加</li></ol><h3 id="使用-webdav-ftp-挂载" tabindex="-1">使用 WebDAV / FTP 挂载 <a class="header-anchor" href="#使用-webdav-ftp-挂载" aria-label="Permalink to &quot;使用 WebDAV / FTP 挂载&quot;">​</a></h3><ol><li>先在个人资料页或管理后台配置好挂载点</li><li>在「添加影片」面板中选择对应的挂载 Tab</li><li>浏览目录，找到视频文件，点击播放</li></ol><hr><h2 id="第九步-开始观影" tabindex="-1">第九步：开始观影 <a class="header-anchor" href="#第九步-开始观影" aria-label="Permalink to &quot;第九步：开始观影&quot;">​</a></h2><p>添加视频后，一切就绪！</p><ul><li><strong>房主</strong>：点击影片列表中的视频，即可开始播放。播放控制（播放、暂停、跳转、倍速）会实时同步给所有观众。</li><li><strong>观众</strong>：加入房间后，播放器会自动同步房主的播放进度，无需任何操作。</li><li><strong>弹幕</strong>：可以在右侧面板发送弹幕，或加载 Bilibili 官方弹幕。</li><li><strong>评论</strong>：在评论区发言，与好友实时交流。</li></ul><hr><h2 id="端口说明" tabindex="-1">端口说明 <a class="header-anchor" href="#端口说明" aria-label="Permalink to &quot;端口说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>端口</th><th>说明</th></tr></thead><tbody><tr><td>后端 REST API + WebSocket</td><td>3333</td><td>HTTP / HTTPS API 及 Socket.IO 实时通信</td></tr><tr><td>前端静态文件服务</td><td>4173</td><td>HTTP 模式下的前端页面，含 API 反向代理</td></tr><tr><td>RTMP 推流</td><td>3334</td><td>OBS 推流端口</td></tr><tr><td>HTTP-FLV 拉流</td><td>3335</td><td>直播流播放（Node Media Server）</td></tr></tbody></table><p>HTTP 模式下，用户通过 <code>http://localhost:4173</code> 访问前端页面，前端自动将 <code>/api</code>、<code>/socket.io</code>、<code>/live</code> 请求转发到后端，无需额外配置。</p><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>了解<a href="/features/rooms">房间的详细设置</a>——密码、观众权限、审批等</li><li>探索<a href="/features/video-sources">更多视频源</a>——Bilibili 大会员、WebDAV、FTP 等</li><li>配置 <a href="/guide/https">HTTPS 与证书</a>——让浏览器不再提示&quot;不安全&quot;</li><li>阅读<a href="/admin/admin-panel">管理后台文档</a>——用户管理、房间管理、系统设置</li></ul>`,87)])])}const u=s(l,[["render",n]]);export{g as __pageData,u as default};
